// ── MangaFire upstream — iframe embed tier (first in the manga chain) ───────
// mangafire.to has one of the largest manga/manhwa libraries anywhere (and
// carries licensed titles like Solo Leveling in full), but the site is a fully
// client-rendered SPA: every URL serves the same 3KB shell, and its JSON API
// (`/api/titles…`) rejects server requests with "Missing token." — the token
// is generated by an obfuscated in-browser VM on top of a Cloudflare edge that
// challenges headless browsers. Server-side listing/scraping is therefore
// intentionally NOT attempted — it would be brittle by design.
//
// Instead Ajest embeds MangaFire's own reader inside a full-screen iframe —
// the same pattern the anime side uses for embed players. Their JavaScript
// runs in the user's browser (passes its own checks), the reader renders with
// its native UI, and nothing on our server ever touches their API.
//
// Embed entry point (their search UI lives on /browse, confirmed in the site's
// own bundle: `/browse?keyword=${…}&sort=relevance:desc`):
//   {MF_BASE}/browse?keyword={title}&sort=relevance:desc
//
// No id namespace: nothing on this tier is addressable server-side, so the
// tier never appears in search results or chapter feeds — it surfaces as an
// embedded reader button on the series page and inside the reader.

export const MF_BASE = 'https://mangafire.to';

/** MangaFire embed URL for a title — their own search, pre-filled + relevance
 *  sorted, so the reader lands on the right series (or its closest matches)
 *  and keeps reading inside the frame. */
export function mfBrowseEmbed(title: string): string {
  return `${MF_BASE}/browse?keyword=${encodeURIComponent(title.trim())}&sort=relevance:desc`;
}
